package com.franco.desco.adapter.out.sqlserver.production;import com.franco.desco.adapter.out.sqlserver.shared.*;import com.franco.desco.application.production.*;import com.franco.desco.application.production.port.out.ProductionPersistencePort;import com.franco.desco.application.shared.*;import com.franco.desco.application.shared.pagination.PageResult;import com.franco.desco.domain.production.ProductionModels;import org.springframework.jdbc.core.simple.SimpleJdbcCall;import org.springframework.stereotype.Component;import java.util.*;
@Component public class ProductionSqlServerAdapter implements ProductionPersistencePort{private final SqlServerPaExecutor e;private final PaPayloadFactory pf;private final SimpleJdbcCall list,get,create,update,confirm,discard;public ProductionSqlServerAdapter(SqlServerPaFactory f,SqlServerPaExecutor e,PaPayloadFactory pf){this.e=e;this.pf=pf;list=f.callWithResultSets("prod","PA_DisponibilidadProduccion_Sel_Listado","items");get=f.callWithResultSets("prod","PA_DisponibilidadProduccion_Sel_Detalle","header","files");create=f.call("prod","PA_DisponibilidadProduccion_Ins_Registro");update=f.call("prod","PA_DisponibilidadProduccion_Upd_Registro");confirm=f.call("prod","PA_DisponibilidadProduccion_Upd_Confirmar");discard=f.call("prod","PA_DisponibilidadProduccion_Upd_Descartar");}
 public PersistenceResult<PageResult<ProductionModels.Summary>>list(ProductionCommands.ListProduction c,SessionIdentity i,RequestMetadata m){var pg=c.page();var f=pg.filtros();var payload=pf.forQuery(i,m,map("filtros",map("estadoEstimacion",f==null?null:f.estadoEstimacion(),"zonaProductivaId",f==null?null:f.zonaProductivaId(),"predioId",f==null?null:f.predioId(),"socioId",f==null?null:f.socioId(),"asociacionId",f==null?null:f.asociacionId(),"variedadPaltaId",f==null?null:f.variedadPaltaId(),"origen",f==null?null:f.origen(),"disponibleDesde",f==null?null:f.disponibleDesde(),"disponibleHasta",f==null?null:f.disponibleHasta()),"paginacion",map("pagina",pg.pagina(),"tamano",pg.tamanio())));var out=e.executeJson(list,payload);return PaAdapterSupport.page(out,rows(out,"items"),pg.pagina(),pg.tamanio(),this::summary,"No se pudo consultar la producción disponible.");}
 public PersistenceResult<ProductionModels.Detail>get(ProductionCommands.Get c,SessionIdentity i,RequestMetadata m){var out=e.executeJson(get,pf.forQuery(i,m,Map.of("produccion",Map.of("disponibilidadProduccionId",c.disponibilidadProduccionId()))));if(!PaAdapterSupport.success(out))return PersistenceResult.error(PaAdapterSupport.message(out,"No se pudo consultar la producción."));var h=one(out,"header");if(h==null)return PersistenceResult.error("La estimación seleccionada no está disponible.");return PersistenceResult.ok(PaAdapterSupport.message(out,"Producción consultada correctamente."),new ProductionModels.Detail(summary(h),SqlValues.string(h,"estadoCultivo"),SqlValues.instant(h,"visitaFechaInicio"),SqlValues.string(h,"visitaEstado"),rows(out,"files").stream().map(this::file).toList()));}
 public PersistenceResult<Long>create(ProductionCommands.Create c,SessionIdentity i,RequestMetadata m){var out=e.executeJson(create,pf.forWrite(i,m,c,Map.of("produccion",map("parcelaCultivoId",c.parcelaCultivoId(),"visitaTecnicaId",c.visitaTecnicaId(),"fechaEstimacion",c.fechaEstimacion(),"disponibleDesde",c.disponibleDesde(),"disponibleHasta",c.disponibleHasta(),"cantidadEstimadaKg",c.cantidadEstimadaKg(),"observacion",c.observacion()))));return PaAdapterSupport.result(out,SqlValues.longValue(out,"nDisponibilidadProduccionId"),"No se pudo registrar la producción.");}
 public PersistenceResult<Void>update(ProductionCommands.Update c,SessionIdentity i,RequestMetadata m){return mut(update,i,m,c,map("disponibilidadProduccionId",c.disponibilidadProduccionId(),"disponibleDesde",c.disponibleDesde(),"disponibleHasta",c.disponibleHasta(),"cantidadEstimadaKg",c.cantidadEstimadaKg(),"observacion",c.observacion()),"No se pudo actualizar la producción.");}public PersistenceResult<Void>confirm(ProductionCommands.Confirm c,SessionIdentity i,RequestMetadata m){return mut(confirm,i,m,c,map("disponibilidadProduccionId",c.disponibilidadProduccionId()),"No se pudo confirmar la producción.");}public PersistenceResult<Void>discard(ProductionCommands.Discard c,SessionIdentity i,RequestMetadata m){return mut(discard,i,m,c,map("disponibilidadProduccionId",c.disponibilidadProduccionId(),"motivo",c.motivo()),"No se pudo descartar la producción.");}
 private PersistenceResult<Void>mut(SimpleJdbcCall call,SessionIdentity i,RequestMetadata m,Object body,Map<String,Object>v,String f){return PaAdapterSupport.result(e.executeJson(call,pf.forWrite(i,m,body,Map.of("produccion",v))),null,f);}private ProductionModels.Summary summary(Map<String,Object>r){return new ProductionModels.Summary(SqlValues.longValue(r,"disponibilidadProduccionId"),SqlValues.instant(r,"fechaEstimacion"),SqlValues.localDate(r,"disponibleDesde"),SqlValues.localDate(r,"disponibleHasta"),SqlValues.decimal(r,"cantidadEstimadaKg"),SqlValues.string(r,"estadoEstimacion"),SqlValues.string(r,"observacion"),SqlValues.longValue(r,"parcelaCultivoId"),SqlValues.intValue(r,"variedadPaltaId"),SqlValues.string(r,"variedad"),SqlValues.longValue(r,"parcelaId"),SqlValues.string(r,"parcelaNombre"),SqlValues.longValue(r,"predioId"),SqlValues.string(r,"predioCodigo"),SqlValues.string(r,"predioNombre"),SqlValues.longValue(r,"zonaProductivaId"),SqlValues.string(r,"zonaProductiva"),SqlValues.longValue(r,"socioId"),SqlValues.string(r,"socioNombre"),SqlValues.longValue(r,"asociacionId"),SqlValues.string(r,"asociacionNombre"),SqlValues.longValue(r,"visitaTecnicaId"),SqlValues.string(r,"origenEstimacion"));}private ProductionModels.File file(Map<String,Object>r){return new ProductionModels.File(SqlValues.longValue(r,"archivoId"),SqlValues.string(r,"nombreOriginal"),SqlValues.string(r,"mimeType"),SqlValues.string(r,"secureUrl"),SqlValues.string(r,"categoria"),SqlValues.string(r,"tipoEvidencia"),SqlValues.string(r,"origenCaptura"),SqlValues.string(r,"descripcion"),SqlValues.instant(r,"fechaCaptura"),SqlValues.instant(r,"fechaCarga"));}private List<Map<String,Object>>rows(Map<String,Object>o,String k){return new PaResultSets(o).rows(k);}private Map<String,Object>one(Map<String,Object>o,String k){return new PaResultSets(o).one(k).orElse(null);}private static Map<String,Object>map(Object...v){Map<String,Object>m=new LinkedHashMap<>();for(int n=0;n<v.length;n+=2)if(v[n+1]!=null)m.put((String)v[n],v[n+1]);return m;}}
